import React, { useState } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter, Link, Navigate, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import { motion } from 'framer-motion'
import { ArrowRight, Award, BookOpen, Check, ChevronRight, CirclePlay, Clock3, FileText, GraduationCap, LayoutDashboard, Lock, Menu, MoreHorizontal, Plus, Search, ShieldCheck, Sparkles, Users, X } from 'lucide-react'
import './styles.css'
import './admin.css'
import './v3.css'
import './v4.css'
import './v5.css'

type Program = { id:string; title:string; description:string; duration:string; modules:number; progress:number; color:string; icon:string }
const programs:Program[] = [
  {id:'administracion-publica',title:'Administración Pública',description:'Liderazgo, instituciones y herramientas para servir con excelencia.',duration:'12 semanas',modules:8,progress:62,color:'blue',icon:'01'},
  {id:'derecho-publico',title:'Derecho Público',description:'Fundamentos del Estado, la legalidad y el interés general.',duration:'10 semanas',modules:7,progress:18,color:'amber',icon:'02'},
  {id:'finanzas-publicas',title:'Administración Financiera Pública',description:'Recursos públicos al servicio del desarrollo nacional.',duration:'14 semanas',modules:9,progress:0,color:'teal',icon:'03'},
  {id:'planeacion-desarrollo',title:'Planeación y Desarrollo Nacional',description:'Estrategias que transforman el territorio y sus comunidades.',duration:'12 semanas',modules:8,progress:0,color:'violet',icon:'04'},
  {id:'gestion-ambiental',title:'Gestión Ambiental y Territorial',description:'Sostenibilidad y ordenamiento para el futuro de Sanza.',duration:'11 semanas',modules:7,progress:0,color:'green',icon:'05'},
  {id:'sector-comercial',title:'Sector Comercial',description:'Competitividad, comercio y crecimiento económico local.',duration:'9 semanas',modules:6,progress:0,color:'coral',icon:'06'},
  {id:'aprendizaje-agricola',title:'Aprendizaje Agrícola',description:'Innovación productiva para la prosperidad rural.',duration:'10 semanas',modules:7,progress:0,color:'olive',icon:'07'}
]
type Account={user:string; password:string; name:string}
const readStore=<T,>(key:string, fallback:T):T=>{try{return JSON.parse(localStorage.getItem(key)||'') as T}catch{return fallback}}
const savedPrograms=()=>readStore<Program[]>('ieso-programs',programs)
const savePrograms=(value:Program[])=>localStorage.setItem('ieso-programs',JSON.stringify(value))
const savedUsers=()=>readStore<Account[]>('ieso-users',[])
const saveUsers=(value:Account[])=>localStorage.setItem('ieso-users',JSON.stringify(value))
const currentUser=()=>localStorage.getItem('ieso-session')
type Module={id:string;programId:string;title:string;content:string;material:string;video:string;quiz:string}
type Announcement={id:string;title:string;body:string;date:string}
const savedModules=()=>readStore<Module[]>('ieso-modules',[])
const saveModules=(value:Module[])=>localStorage.setItem('ieso-modules',JSON.stringify(value))
const savedAnnouncements=()=>readStore<Announcement[]>('ieso-announcements',[])
const saveAnnouncements=(value:Announcement[])=>localStorage.setItem('ieso-announcements',JSON.stringify(value))
type Quiz={id:string;programId:string;moduleId?:string;question:string;options:string[];correct:number;feedback?:string}
const savedQuizzes=()=>readStore<Quiz[]>('ieso-quizzes',[])
const saveQuizzes=(value:Quiz[])=>localStorage.setItem('ieso-quizzes',JSON.stringify(value))
type ProgressRecord={completed:string[];finalPassed:boolean}
const progressKey=(user:string,program:string)=>`ieso-progress-${user}-${program}`
const readProgress=(user:string,program:string)=>readStore<ProgressRecord>(progressKey(user,program),{completed:[],finalPassed:false})
const saveProgress=(user:string,program:string,value:ProgressRecord)=>localStorage.setItem(progressKey(user,program),JSON.stringify(value))
type Enrollment={user:string;programIds:string[]}
type Grade={id:string;user:string;programId:string;moduleId?:string;final:boolean;score:number;passed:boolean;date:string}
const savedEnrollments=()=>readStore<Enrollment[]>('ieso-enrollments',[])
const saveEnrollments=(value:Enrollment[])=>localStorage.setItem('ieso-enrollments',JSON.stringify(value))
const hasProgramAccess=(user:string,programId:string)=>savedEnrollments().find(x=>x.user===user)?.programIds.includes(programId)===true
const savedGrades=()=>readStore<Grade[]>('ieso-grades',[])
const saveGrades=(value:Grade[])=>localStorage.setItem('ieso-grades',JSON.stringify(value))

const Logo=({light=false}:{light?:boolean})=><div className={'logo '+(light?'light':'')}><div className="logo-mark">I</div><div><strong>IESO</strong><span>Instituto de Educación Superior Oficial</span><small>REINO DE SANZA</small></div></div>
const Progress=({value}:{value:number})=><div className="progress"><i style={{width:`${value}%`}} /></div>
function Nav(){ const [open,setOpen]=useState(false); return <header><Link to="/" className="brand"><Logo/></Link><nav className={open?'open':''}><Link to="/programas">Programas</Link><a href="#instituto">El Instituto</a><a href="#ayuda">Ayuda</a><Link className="outline-btn" to="/ingresar">Iniciar sesión <ArrowRight size={15}/></Link></nav><button className="menu" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></header> }
function Hero(){return <section className="hero"><div className="hero-copy"><div className="eyebrow"><Sparkles size={14}/> EDUCACIÓN PÚBLICA · REINO DE SANZA</div><h1>Educación superior pública para construir el <em>futuro</em> de Sanza.</h1><p>Accede gratuitamente a programas de formación diseñados para fortalecer el servicio público, el desarrollo económico y el crecimiento del Reino de Sanza.</p><div className="actions"><Link className="primary-btn" to="/programas">Explorar programas <ArrowRight size={17}/></Link><Link className="text-btn" to="/ingresar">Iniciar sesión <ChevronRight size={17}/></Link></div></div><div className="hero-art"><div className="sun"></div><div className="arch arch-a"></div><div className="arch arch-b"></div><div className="art-card card-one"><GraduationCap/><span>Aprendizaje<br/><b>sin fronteras</b></span></div><div className="art-card card-two"><span>FORMACIÓN</span><b>Acceso<br/>público</b></div><div className="ribbon">IESO · SANZA · IESO · SANZA · IESO · SANZA ·</div></div></section>}
function ProgramCard({p}:{p:Program}){return <motion.article className="program-card" whileHover={{y:-5}} transition={{duration:.25}}><div className={'program-visual '+p.color}><span>{p.icon}</span><div className="visual-shape"></div><BookOpen size={24}/></div><div className="program-content"><div className="program-meta"><span>{p.duration}</span><span>{p.modules} módulos</span></div><h3>{p.title}</h3><p>{p.description}</p>{p.progress>0&&<div className="card-progress"><div><span>Tu avance</span><b>{p.progress}%</b></div><Progress value={p.progress}/></div>}<Link to={`/curso/${p.id}`} className="card-link">Ingresar <ArrowRight size={16}/></Link></div></motion.article>}
function Home(){return <><Nav/><main><Hero/><section className="program-section"><div className="section-head"><div><div className="eyebrow">OFERTA ACADÉMICA</div><h2>Programas que impulsan<br/><em>el bien común.</em></h2></div><Link to="/programas" className="see-all">Ver todos los programas <ArrowRight size={17}/></Link></div><div className="program-grid">{programs.slice(0,3).map(p=><ProgramCard key={p.id} p={p}/>)}</div></section><section id="instituto" className="institution"><div className="seal"><ShieldCheck size={44}/><span>REINO<br/>DE SANZA</span></div><div><div className="eyebrow">NUESTRA MISIÓN</div><h2>Conocimiento que se convierte<br/>en <em>capacidad pública.</em></h2></div><p>El IESO forma a las personas que hacen avanzar a Sanza. Nuestra educación modular combina rigor académico, aplicación real y acceso universal.</p></section></main><footer><Logo light/><span>© 2026 Instituto de Educación Superior Oficial de Sanza</span></footer></>}
function Programs(){return <><Nav/><main className="listing"><div className="listing-intro"><div className="eyebrow">OFERTA ACADÉMICA</div><h1>Encuentra tu próximo<br/><em>propósito.</em></h1><p>Programas gratuitos, modulares y orientados a los retos reales de Sanza.</p></div><div className="catalog-tools"><div className="search"><Search size={18}/><input placeholder="Buscar programa"/></div><button>Todos los campos <ChevronRight size={15}/></button></div><div className="program-grid all">{programs.map(p=><ProgramCard key={p.id} p={p}/>)}</div></main><footer><Logo light/></footer></>}
const lessons=['La organización del Estado sanzano','Principios del servicio público','Ética e integridad institucional','Estructura de la administración'];
function Course(){const {id}=useParams(); const p=programs.find(x=>x.id===id)||programs[0]; const [active,setActive]=useState(0);return <><Nav/><main className="course"><div className="crumb"><Link to="/programas">Programas</Link><ChevronRight size={14}/><span>{p.title}</span></div><section className="course-head"><div><div className="eyebrow">PROGRAMA ACADÉMICO · {p.duration.toUpperCase()}</div><h1>{p.title}</h1><p>{p.description} Un recorrido diseñado por especialistas del Instituto para quienes desean aportar al país desde una gestión moderna y responsable.</p><div className="course-facts"><span><Clock3 size={17}/>{p.duration}</span><span><BookOpen size={17}/>{p.modules} módulos</span><span><Award size={17}/>Certificación IESO</span></div></div><div className={'course-cover '+p.color}><span>IESO</span><GraduationCap size={68}/><b>{p.title}</b></div></section><div className="course-body"><aside><div className="aside-title">CONTENIDO DEL PROGRAMA</div>{[1,2,3,4].map((m,i)=><div className={'module-nav '+(i===0?'selected':'')} key={m}><div><b>Módulo 0{m}</b><span>{i===0?'Fundamentos de la gestión pública':i===1?'Marco institucional':i===2?'Planificación y resultados':'Evaluación final'}</span></div>{i===0?<Check size={17}/>:<Lock size={15}/>}</div>)}</aside><section className="lesson"><div className="lesson-top"><span>MÓDULO 01</span><b>62% completado</b></div><Progress value={62}/><h2>Fundamentos de la gestión pública</h2><p>Comprende las bases del servicio público y el rol de las instituciones en el desarrollo de Sanza.</p><div className="lesson-list">{lessons.map((l,i)=><button onClick={()=>setActive(i)} className={active===i?'active':''} key={l}><span>{active>i?<Check size={16}/>:i+1}</span><div><b>{l}</b><small><CirclePlay size={14}/> Video · {12+i*3} min</small></div>{active===i&&<CirclePlay size={20}/>}</button>)}</div><Link className="primary-btn continue" to={`/evaluacion/${p.id}`}>Continuar aprendizaje <ArrowRight size={17}/></Link></section></div></main></>}
function Assessment(){const {id}=useParams(); const p=programs.find(x=>x.id===id)||programs[0]; const [answer,setAnswer]=useState<number|null>(null); const [submitted,setSubmitted]=useState(false);return <><Nav/><main className="assessment"><div className="exam-label"><FileText/> EVALUACIÓN DEL MÓDULO 01</div><h1>Comprueba lo que<br/>has <em>aprendido.</em></h1><p>Responde las preguntas para finalizar el módulo. Necesitas una nota mínima de 70%.</p><div className="exam-progress"><span>Pregunta 1 de 5</span><Progress value={20}/><span>20%</span></div><section className="question"><div className="question-number">01</div><h2>¿Cuál es el propósito principal de la administración pública?</h2><p>Selecciona la respuesta más adecuada.</p>{['Gestionar recursos para el beneficio particular.','Servir al interés general y satisfacer las necesidades de la ciudadanía.','Ejercer control exclusivamente sobre las empresas privadas.','Crear leyes sin intervención de otras instituciones.'].map((x,i)=><button onClick={()=>!submitted&&setAnswer(i)} className={'option '+(answer===i?'chosen ':'')+(submitted&&i===1?'correct':'')} key={x}><i>{String.fromCharCode(65+i)}</i>{x}{submitted&&i===1&&<Check size={19}/>}</button>)}{submitted&&<div className="feedback"><Check size={18}/><span><b>¡Excelente!</b> La administración pública existe para hacer efectivo el interés general.</span></div>}<button disabled={answer===null} onClick={()=>setSubmitted(true)} className="primary-btn">{submitted?'Siguiente pregunta':'Confirmar respuesta'} <ArrowRight size={17}/></button></section><div className="attempt"><ShieldCheck/><span><b>Intento 1 de 3</b><br/>Tu progreso se guarda automáticamente.</span></div></main></>}
function Login(){const [user,setUser]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState(''); const nav=useNavigate(); const submit=(e:React.FormEvent)=>{e.preventDefault();if(user==='admin'&&password==='Santiago@2015')nav('/gestion');else setError('No encontramos una cuenta autorizada con estos datos.')};return <main className="login-page"><Link to="/"><Logo/></Link><div className="login-card"><div className="login-symbol"><GraduationCap/></div><h1>Bienvenido al IESO</h1><p>Ingresa con las credenciales asignadas por el Instituto.</p><form onSubmit={submit}><label>Usuario<input value={user} onChange={e=>setUser(e.target.value)} placeholder="Tu usuario" autoComplete="username"/></label><label>Contraseña<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Tu contraseña" autoComplete="current-password"/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-btn">Iniciar sesión <ArrowRight size={17}/></button></form><small>Las cuentas son creadas exclusivamente por la administración del IESO.</small></div></main>}
function Admin(){return <div className="admin"><aside className="admin-nav"><Logo light/><div className="admin-label">ADMINISTRACIÓN</div>{[[LayoutDashboard,'Vista general'],[BookOpen,'Programas'],[Users,'Usuarios'],[FileText,'Evaluaciones'],[Award,'Certificados']].map(([I,label]:any,i)=><a className={i===0?'active':''} key={label}><I size={18}/>{label}</a>)}<div className="admin-bottom"><a><Lock size={17}/>Cerrar sesión</a></div></aside><main className="admin-main"><div className="admin-top"><div><span>PANEL IESO</span><h1>Buenos días, Administrador.</h1></div><button className="add-btn"><Plus size={17}/>Nuevo programa</button></div><section className="stat-grid">{[['1,842','Estudiantes activos',Users],['7','Programas publicados',BookOpen],['84%','Tasa de finalización',Award],['24','Certificados este mes',FileText]].map(([number,label,Icon]:any)=><article><div><span>{label}</span><b>{number}</b><small>↗ 12% este mes</small></div><i><Icon size={20}/></i></article>)}</section><section className="admin-table"><div className="table-head"><div><h2>Programas académicos</h2><p>Gestiona la oferta formativa del Instituto.</p></div><button className="plain-btn">Ver todos <ArrowRight size={16}/></button></div><div className="table"><div className="tr th"><span>PROGRAMA</span><span>ESTUDIANTES</span><span>MÓDULOS</span><span>ESTADO</span><span></span></div>{programs.slice(0,4).map(p=><div className="tr" key={p.id}><span><i className={'mini-cover '+p.color}>{p.icon}</i><b>{p.title}</b></span><span>{Math.floor(86+Math.random()*200)}</span><span>{p.modules}</span><span><em>Publicado</em></span><span><MoreHorizontal size={20}/></span></div>)}</div></section></main></div>}
function RequireUser({children}:{children:React.ReactNode}){return currentUser()?<>{children}</>:<Navigate to="/ingresar" replace/>}
function LoginV2(){const [user,setUser]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const nav=useNavigate();const submit=(e:React.FormEvent)=>{e.preventDefault();const admin=user==='admin'&&password==='Santiago@2015';const account=savedUsers().find(x=>x.user===user&&x.password===password);if(!admin&&!account){setError('No encontramos una cuenta autorizada con estos datos.');return}localStorage.setItem('ieso-session',user);nav(admin?'/gestion':'/programas')};return <main className="login-page"><Link to="/"><Logo/></Link><div className="login-card"><div className="login-symbol"><GraduationCap/></div><h1>Bienvenido al IESO</h1><p>Ingresa con las credenciales asignadas por el Instituto.</p><form onSubmit={submit}><label>Usuario<input value={user} onChange={e=>setUser(e.target.value)} placeholder="Tu usuario"/></label><label>Contraseña<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Tu contraseña"/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-btn">Iniciar sesión <ArrowRight size={17}/></button></form><small>Las cuentas son creadas exclusivamente por la administración del IESO.</small></div></main>}
function AdminV2(){const nav=useNavigate();const [tab,setTab]=useState('Programas');const [items,setItems]=useState(savedPrograms());const [users,setUsers]=useState(savedUsers());const [name,setName]=useState('');const [detail,setDetail]=useState('');const [notice,setNotice]=useState('');const addProgram=()=>{if(!name.trim())return;const next=[...items,{id:name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title:name,description:detail||'Programa formativo del Instituto de Educación Superior Oficial de Sanza.',duration:'10 semanas',modules:0,progress:0,color:'blue',icon:String(items.length+1).padStart(2,'0')}];setItems(next);savePrograms(next);setName('');setDetail('');setNotice('Programa creado y publicado.')};const addUser=()=>{if(!name.trim()||!detail.trim())return;const next=[...users,{user:name,password:detail,name}];setUsers(next);saveUsers(next);setName('');setDetail('');setNotice('Cuenta creada. La persona ya puede iniciar sesión.')};const removeProgram=(id:string)=>{const next=items.filter(x=>x.id!==id);setItems(next);savePrograms(next);setNotice('Programa retirado.')};if(currentUser()!=='admin')return <Navigate to="/ingresar" replace/>;const addMode=tab==='Usuarios'?'Usuario':'Programa';return <div className="admin"><aside className="admin-nav"><Logo light/><div className="admin-label">ADMINISTRACIÓN</div>{[[BookOpen,'Programas'],[Users,'Usuarios'],[FileText,'Anuncios'],[FileText,'Módulos'],[Award,'Certificados']].map(([I,label]:any)=><a onClick={()=>{setTab(label);setNotice('');setName('');setDetail('')}} className={tab===label?'active':''} key={label}><I size={18}/>{label}</a>)}<div className="admin-bottom"><a onClick={()=>{localStorage.removeItem('ieso-session');nav('/')}}><Lock size={17}/>Cerrar sesión</a></div></aside><main className="admin-main"><div className="admin-top"><div><span>GESTIÓN IESO</span><h1>{tab}</h1></div></div>{tab==='Programas'&&<><section className="admin-form"><h2>Crear programa</h2><input value={name} onChange={e=>setName(e.target.value)} placeholder="Nombre del programa"/><input value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Descripción breve"/><button className="add-btn" onClick={addProgram}><Plus size={17}/>Crear y publicar</button></section><section className="admin-table"><div className="table-head"><div><h2>Oferta académica</h2><p>Los cambios se guardan en este navegador.</p></div></div>{items.map(p=><div className="tr" key={p.id}><span><i className={'mini-cover '+p.color}>{p.icon}</i><b>{p.title}</b></span><span>{p.modules} módulos</span><span><em>Publicado</em></span><button className="plain-btn" onClick={()=>removeProgram(p.id)}>Eliminar</button></div>)}</section></>}{tab==='Usuarios'&&<><section className="admin-form"><h2>Crear cuenta de estudiante</h2><input value={name} onChange={e=>setName(e.target.value)} placeholder="Usuario"/><input value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Contraseña temporal"/><button className="add-btn" onClick={addUser}><Plus size={17}/>Crear cuenta</button></section><section className="admin-table"><div className="table-head"><div><h2>Usuarios autorizados</h2><p>Solo estas cuentas podrán acceder a los cursos.</p></div></div>{users.length?users.map(u=><div className="tr" key={u.user}><span><b>{u.user}</b></span><span>Estudiante</span><span><em>Activo</em></span></div>):<p className="empty">Aún no hay cuentas de estudiantes creadas.</p>}</section></>}{tab==='Módulos'&&<section className="admin-form"><h2>Administrar módulos</h2><p>Selecciona un programa desde la oferta académica para añadir sus módulos y materiales. La estructura de curso se muestra al estudiante tras iniciar sesión.</p><button className="add-btn" onClick={()=>setNotice('Módulo guardado como borrador.')}>Guardar módulo</button></section>}{tab==='Anuncios'&&<section className="admin-form"><h2>Publicar anuncio institucional</h2><input value={name} onChange={e=>setName(e.target.value)} placeholder="Título del anuncio"/><input value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Mensaje para estudiantes"/><button className="add-btn" onClick={()=>{setNotice('Anuncio publicado.');setName('');setDetail('')}}>Publicar anuncio</button></section>}{tab==='Certificados'&&<section className="admin-form"><h2>Certificados institucionales</h2><p>Los certificados se habilitarán para cada estudiante cuando complete todos los módulos y apruebe las evaluaciones.</p><button className="add-btn" onClick={()=>setNotice('Certificado generado para revisión.')}>Generar certificado</button></section>}{notice&&<div className="admin-notice"><Check size={17}/>{notice}</div>}</main></div>}
function NavV3(){const nav=useNavigate();const session=currentUser();return <header><Link to="/" className="brand"><Logo/></Link><nav><Link to="/programas">Programas</Link><Link to="/anuncios">Anuncios</Link>{session?<button className="outline-btn" onClick={()=>{localStorage.removeItem('ieso-session');nav('/')}}>Cerrar sesión <Lock size={15}/></button>:<Link className="outline-btn" to="/ingresar">Iniciar sesión <ArrowRight size={15}/></Link>}</nav></header>}
function HomeV3(){return <><NavV3/><main><Hero/><section className="program-section"><div className="section-head"><div><div className="eyebrow">OFERTA ACADÉMICA</div><h2>Programas que impulsan<br/><em>el bien común.</em></h2></div><Link to="/programas" className="see-all">Ver todos los programas <ArrowRight size={17}/></Link></div><div className="program-grid">{savedPrograms().slice(0,3).map(p=><ProgramCard key={p.id} p={p}/>)}</div></section></main><footer><Logo light/><span>© 2026 Instituto de Educación Superior Oficial de Sanza</span></footer></>}
function ProgramsV3(){const [items,setItems]=useState(savedPrograms());const [query,setQuery]=useState('');const shown=items.filter(p=>p.title.toLowerCase().includes(query.toLowerCase()));return <><NavV3/><main className="listing"><div className="listing-intro"><div className="eyebrow">OFERTA ACADÉMICA</div><h1>Encuentra tu próximo<br/><em>propósito.</em></h1><p>Programas gratuitos, modulares y orientados a los retos reales de Sanza.</p></div><div className="catalog-tools"><div className="search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar programa"/></div></div><div className="program-grid all">{shown.map(p=><ProgramCard key={p.id} p={p}/>)}</div></main><footer><Logo light/></footer></>}
function Announcements(){const notices=savedAnnouncements();return <><NavV3/><main className="listing announcements"><div className="listing-intro"><div className="eyebrow">COMUNICACIONES IESO</div><h1>Información para la<br/><em>comunidad.</em></h1></div>{notices.length?notices.map(n=><article className="notice-card" key={n.id}><small>{n.date}</small><h2>{n.title}</h2><p>{n.body}</p></article>):<p className="no-content">No hay anuncios publicados en este momento.</p>}</main></>}
function CourseV3(){const {id}=useParams();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const modules=savedModules().filter(m=>m.programId===p.id);const [selected,setSelected]=useState(0);if(!currentUser())return <Navigate to="/ingresar" replace/>;const active=modules[selected];return <><NavV3/><main className="course"><div className="crumb"><Link to="/programas">Programas</Link><ChevronRight size={14}/><span>{p.title}</span></div><section className="course-head"><div><div className="eyebrow">PROGRAMA ACADÉMICO · {p.duration.toUpperCase()}</div><h1>{p.title}</h1><p>{p.description}</p><div className="course-facts"><span><Clock3 size={17}/>{p.duration}</span><span><BookOpen size={17}/>{modules.length||p.modules} módulos</span><span><Award size={17}/>Certificación IESO</span></div></div><div className={'course-cover '+p.color}><span>IESO</span><GraduationCap size={68}/><b>{p.title}</b></div></section><div className="course-body"><aside><div className="aside-title">CONTENIDO DEL PROGRAMA</div>{(modules.length?modules:[{id:'base',title:'Introducción al programa'} as Module]).map((m,i)=><button className={'module-nav '+(selected===i?'selected':'')} onClick={()=>setSelected(i)} key={m.id}><div><b>MÓDULO {String(i+1).padStart(2,'0')}</b><span>{m.title}</span></div><ChevronRight size={15}/></button>)}</aside><section className="lesson"><div className="lesson-top"><span>MÓDULO {String(selected+1).padStart(2,'0')}</span><b>Contenido formativo</b></div><h2>{active?.title||'Introducción al programa'}</h2><p>{active?.content||'El administrador publicará los módulos, materiales y actividades de este programa.'}</p>{active?.video&&<a className="resource" href={active.video} target="_blank"> <CirclePlay size={18}/> Ver video de la lección</a>}{active?.material&&<a className="resource" href={active.material} target="_blank"><FileText size={18}/> Abrir documento de apoyo</a>}<Link className="primary-btn continue" to={`/evaluacion/${p.id}`}>Realizar evaluación <ArrowRight size={17}/></Link></section></div></main></>}
function Certificate(){const {id}=useParams();if(!currentUser())return <Navigate to="/ingresar" replace/>;const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];return <main className="certificate-page"><div className="certificate"><div className="cert-brand"><Logo/><ShieldCheck size={42}/></div><div className="eyebrow">CERTIFICADO DE FINALIZACIÓN</div><h1>Instituto de Educación Superior Oficial de Sanza</h1><p>Certifica que</p><h2>{currentUser()}</h2><p>ha completado satisfactoriamente el programa</p><h3>{p.title}</h3><div className="cert-details"><span>Emitido el {new Date().toLocaleDateString('es-CO')}</span><span>Código IESO-{p.id.slice(0,5).toUpperCase()}-2026</span></div><div className="cert-sign"><span>Dirección Académica<br/><b>IESO · Reino de Sanza</b></span><i>▦</i></div></div><button className="primary-btn" onClick={()=>window.print()}>Imprimir certificado</button></main>}
function AdminFull(){const nav=useNavigate();const [tab,setTab]=useState('Programas');const [ps,setPs]=useState(savedPrograms());const [us,setUs]=useState(savedUsers());const [ms,setMs]=useState(savedModules());const [title,setTitle]=useState('');const [body,setBody]=useState('');const [programId,setProgramId]=useState(ps[0]?.id||'');const [notice,setNotice]=useState('');if(currentUser()!=='admin')return <Navigate to="/ingresar" replace/>;const saveP=(next:Program[])=>{setPs(next);savePrograms(next)};const createProgram=()=>{if(!title)return;saveP([...ps,{id:title.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title,description:body||'Programa académico del IESO.',duration:'10 semanas',modules:0,progress:0,color:'blue',icon:String(ps.length+1).padStart(2,'0')}]);setTitle('');setBody('');setNotice('Programa creado. Ya es visible en la oferta académica.')};const createUser=()=>{if(!title||!body)return;const next=[...us,{user:title,password:body,name:title}];setUs(next);saveUsers(next);setTitle('');setBody('');setNotice('Cuenta autorizada creada.')};const createModule=()=>{if(!title||!programId)return;const next=[...ms,{id:crypto.randomUUID(),programId,title,content:body,material:'',video:'',quiz:''}];setMs(next);saveModules(next);saveP(ps.map(p=>p.id===programId?{...p,modules:next.filter(m=>m.programId===p.id).length}:p));setTitle('');setBody('');setNotice('Módulo publicado en el curso.')};const publish=()=>{if(!title||!body)return;saveAnnouncements([{id:crypto.randomUUID(),title,body,date:new Date().toLocaleDateString('es-CO')},...savedAnnouncements()]);setTitle('');setBody('');setNotice('Anuncio publicado.')};const remove=(kind:string,id:string)=>{if(kind==='p')saveP(ps.filter(p=>p.id!==id));if(kind==='u'){const n=us.filter(u=>u.user!==id);setUs(n);saveUsers(n)}if(kind==='m'){const n=ms.filter(m=>m.id!==id);setMs(n);saveModules(n)}setNotice('Elemento eliminado.')};const heading:any={Programas:['Crear programa','Nombre del programa','Descripción'],Usuarios:['Crear cuenta','Usuario','Contraseña temporal'],Módulos:['Crear módulo','Título del módulo','Contenido o instrucciones'],Anuncios:['Publicar anuncio','Título','Mensaje institucional']}[tab];return <div className="admin"><aside className="admin-nav"><Logo light/><div className="admin-label">ADMINISTRACIÓN</div>{[[BookOpen,'Programas'],[Users,'Usuarios'],[FileText,'Módulos'],[Sparkles,'Anuncios'],[Award,'Certificados']].map(([I,label]:any)=><a className={tab===label?'active':''} onClick={()=>{setTab(label);setNotice('')}} key={label}><I size={18}/>{label}</a>)}<div className="admin-bottom"><a onClick={()=>{localStorage.removeItem('ieso-session');nav('/')}}><Lock size={17}/>Cerrar sesión</a></div></aside><main className="admin-main"><div className="admin-top"><div><span>GESTIÓN IESO</span><h1>{tab}</h1></div></div>{tab==='Certificados'?<section className="admin-form"><h2>Generar certificado</h2><p>Selecciona un programa; el certificado se puede entregar al estudiante que haya completado sus módulos y evaluación.</p><select value={programId} onChange={e=>setProgramId(e.target.value)}>{ps.map(p=><option value={p.id}>{p.title}</option>)}</select><Link className="add-btn" to={`/certificado/${programId}`}>Vista previa <ArrowRight size={16}/></Link></section>:<><section className="admin-form"><h2>{heading[0]}</h2>{tab==='Módulos'&&<select value={programId} onChange={e=>setProgramId(e.target.value)}>{ps.map(p=><option value={p.id}>{p.title}</option>)}</select>}<input value={title} onChange={e=>setTitle(e.target.value)} placeholder={heading[1]}/><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder={heading[2]}/><button className="add-btn" onClick={tab==='Programas'?createProgram:tab==='Usuarios'?createUser:tab==='Módulos'?createModule:publish}><Plus size={17}/>Guardar</button></section><section className="admin-table"><div className="table-head"><div><h2>{tab} gestionados</h2><p>Los cambios se guardan para esta plataforma.</p></div></div>{tab==='Programas'&&ps.map(x=><div className="tr" key={x.id}><span><i className={'mini-cover '+x.color}>{x.icon}</i><b>{x.title}</b></span><span>{x.modules} módulos</span><span><em>Publicado</em></span><button className="plain-btn" onClick={()=>remove('p',x.id)}>Eliminar</button></div>)}{tab==='Usuarios'&&(us.length?us.map(x=><div className="tr" key={x.user}><span><b>{x.user}</b></span><span>Estudiante</span><span><em>Autorizado</em></span><button className="plain-btn" onClick={()=>remove('u',x.user)}>Eliminar</button></div>):<p className="empty">No hay usuarios creados.</p>)}{tab==='Módulos'&&(ms.length?ms.map(x=><div className="tr" key={x.id}><span><b>{x.title}</b></span><span>{ps.find(p=>p.id===x.programId)?.title}</span><span><em>Publicado</em></span><button className="plain-btn" onClick={()=>remove('m',x.id)}>Eliminar</button></div>):<p className="empty">No hay módulos creados.</p>)}</section></>}{notice&&<div className="admin-notice"><Check size={17}/>{notice}</div>}</main></div>}
function AssessmentV3(){const {id}=useParams();const quiz=savedQuizzes().filter(q=>q.programId===id);const questions=quiz.length?quiz:[{id:'base',programId:id||'',question:'¿Cuál es el propósito principal de la administración pública?',options:['Gestionar recursos para el beneficio particular.','Servir al interés general y satisfacer las necesidades de la ciudadanía.','Ejercer control exclusivamente sobre las empresas privadas.','Crear leyes sin intervención de otras instituciones.'],correct:1}];const [step,setStep]=useState(0);const [answer,setAnswer]=useState<number|null>(null);const [score,setScore]=useState(0);const [done,setDone]=useState(false);if(!currentUser())return <Navigate to="/ingresar" replace/>;const q=questions[step];const submit=()=>{if(answer===null)return;const next=score+(answer===q.correct?1:0);if(step===questions.length-1){setScore(next);setDone(true)}else{setScore(next);setStep(step+1);setAnswer(null)}};return <><NavV3/><main className="assessment"><div className="exam-label"><FileText/> EVALUACIÓN DEL PROGRAMA</div>{done?<section className="question result"><Award size={35}/><h2>{score/questions.length>=.7?'Evaluación aprobada':'Evaluación no aprobada'}</h2><p>Obtuviste {Math.round(score/questions.length*100)}%. {score/questions.length>=.7?'Ya puedes solicitar tu certificado institucional.':'Puedes revisar el contenido e intentarlo nuevamente.'}</p>{score/questions.length>=.7&&<Link className="primary-btn" to={`/certificado/${id}`}>Ver certificado <Award size={17}/></Link>}</section>:<><h1>Comprueba lo que<br/>has <em>aprendido.</em></h1><div className="exam-progress"><span>Pregunta {step+1} de {questions.length}</span><Progress value={(step+1)/questions.length*100}/><span>{Math.round((step+1)/questions.length*100)}%</span></div><section className="question"><div className="question-number">{String(step+1).padStart(2,'0')}</div><h2>{q.question}</h2><p>Selecciona la respuesta más adecuada.</p>{q.options.map((x,i)=><button onClick={()=>setAnswer(i)} className={'option '+(answer===i?'chosen':'')} key={x}><i>{String.fromCharCode(65+i)}</i>{x}</button>)}<button disabled={answer===null} onClick={submit} className="primary-btn">{step===questions.length-1?'Finalizar evaluación':'Siguiente pregunta'} <ArrowRight size={17}/></button></section></>}</main></>}
function ProgramCardV4({p}:{p:Program}){const signed=!!currentUser();return <motion.article className="program-card" whileHover={{y:-5}}><div className={'program-visual '+p.color}><span>{p.icon}</span><div className="visual-shape"/><BookOpen size={24}/></div><div className="program-content"><div className="program-meta"><span>{p.duration}</span><span>{p.modules} módulos</span></div><h3>{p.title}</h3><p>{p.description}</p>{signed&&p.progress>0&&<div className="card-progress"><div><span>Tu avance</span><b>{p.progress}%</b></div><Progress value={p.progress}/></div>}<Link to={`/curso/${p.id}`} className="card-link">Ingresar <ArrowRight size={16}/></Link></div></motion.article>}
function HomeV4(){return <><NavV3/><main><Hero/><section className="program-section"><div className="section-head"><div><div className="eyebrow">OFERTA ACADÉMICA</div><h2>Programas que impulsan<br/><em>el bien común.</em></h2></div><Link to="/programas" className="see-all">Ver todos los programas <ArrowRight size={17}/></Link></div><div className="program-grid">{savedPrograms().slice(0,3).map(p=><ProgramCardV4 key={p.id} p={p}/>)}</div></section></main><footer><Logo light/></footer></>}
function ProgramsV4(){const [query,setQuery]=useState('');const all=savedPrograms().filter(p=>p.title.toLowerCase().includes(query.toLowerCase()));return <><NavV3/><main className="listing"><div className="listing-intro"><div className="eyebrow">OFERTA ACADÉMICA</div><h1>Encuentra tu próximo<br/><em>propósito.</em></h1></div><div className="catalog-tools"><div className="search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar programa"/></div></div><div className="program-grid all">{all.map(p=><ProgramCardV4 key={p.id} p={p}/>)}</div></main></>}
function CourseV4(){const {id}=useParams();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const user=currentUser();const modules=savedModules().filter(m=>m.programId===p.id);const progress=user?readProgress(user,p.id):{completed:[],finalPassed:false};const [selected,setSelected]=useState(0);if(!user)return <Navigate to="/ingresar" replace/>;const allDone=modules.length>0&&modules.every(m=>progress.completed.includes(m.id));const active=modules[selected];return <><NavV3/><main className="course"><div className="crumb"><Link to="/programas">Programas</Link><ChevronRight size={14}/><span>{p.title}</span></div><section className="course-head"><div><div className="eyebrow">PROGRAMA ACADÉMICO</div><h1>{p.title}</h1><p>{p.description}</p><div className="course-facts"><span><Clock3 size={17}/>{p.duration}</span><span><BookOpen size={17}/>{modules.length} módulos</span><span><Award size={17}/>Certificación IESO</span></div></div><div className={'course-cover '+p.color}><span>IESO</span><GraduationCap size={68}/><b>{p.title}</b></div></section><div className="course-body"><aside><div className="aside-title">CONTENIDO DEL PROGRAMA</div>{modules.map((m,i)=>{const done=progress.completed.includes(m.id);const unlocked=i===0||progress.completed.includes(modules[i-1].id);return <button disabled={!unlocked} className={'module-nav '+(selected===i?'selected':'')} onClick={()=>setSelected(i)} key={m.id}><div><b>MÓDULO {String(i+1).padStart(2,'0')}</b><span>{m.title}</span></div>{done?<Check size={16}/>:unlocked?<ChevronRight size={15}/>:<Lock size={15}/>}</button>})}</aside><section className="lesson">{active?<><div className="lesson-top"><span>MÓDULO {String(selected+1).padStart(2,'0')}</span><b>{progress.completed.includes(active.id)?'Completado':'Disponible'}</b></div><h2>{active.title}</h2><p>{active.content}</p>{active.video&&<a className="resource" href={active.video} target="_blank"><CirclePlay size={18}/> Ver video</a>}{active.material&&<a className="resource" href={active.material} target="_blank"><FileText size={18}/> Descargar material</a>}{!progress.completed.includes(active.id)&&<Link className="primary-btn continue" to={`/evaluacion/${p.id}?module=${active.id}`}>Presentar evaluación del módulo <ArrowRight size={17}/></Link>}</>:<p className="no-content">El administrador aún no ha publicado módulos para este programa.</p>}{allDone&&<div className="final-box"><Award size={25}/><div><b>Has completado todos los módulos.</b><span>Presenta la evaluación final para obtener el certificado.</span></div><Link className="primary-btn" to={`/evaluacion/${p.id}?final=1`}>Evaluación final</Link></div>}</section></div></main></>}
function AssessmentV4(){const {id}=useParams();const search=new URLSearchParams(location.search);const moduleId=search.get('module');const final=search.get('final')==='1';const user=currentUser();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const modules=savedModules().filter(m=>m.programId===p.id);const progress=user?readProgress(user,p.id):{completed:[],finalPassed:false};const questions=savedQuizzes().filter(q=>q.programId===p.id&&((final&&!q.moduleId)||(!final&&q.moduleId===moduleId)));const [step,setStep]=useState(0);const [answer,setAnswer]=useState<number|null>(null);const [score,setScore]=useState(0);const [done,setDone]=useState(false);if(!user)return <Navigate to="/ingresar" replace/>;if(final&&!modules.every(m=>progress.completed.includes(m.id)))return <Navigate to={`/curso/${p.id}`} replace/>;if(!final&&(!moduleId||!modules.find(m=>m.id===moduleId)))return <Navigate to={`/curso/${p.id}`} replace/>;if(!questions.length)return <><NavV3/><main className="assessment"><section className="question"><h2>Evaluación pendiente de configurar</h2><p>El administrador debe publicar las preguntas de esta evaluación antes de que puedas realizarla.</p><Link className="primary-btn" to={`/curso/${p.id}`}>Volver al curso</Link></section></main></>;const q=questions[step];const submit=()=>{if(answer===null)return;const next=score+(answer===q.correct?1:0);if(step<questions.length-1){setScore(next);setStep(step+1);setAnswer(null);return}const passed=next/questions.length>=.7;if(passed){const updated=final?{...progress,finalPassed:true}:{...progress,completed:[...new Set([...progress.completed,moduleId!])]};saveProgress(user,p.id,updated)}setScore(next);setDone(true)};return <><NavV3/><main className="assessment"><div className="exam-label"><FileText/> {final?'EVALUACIÓN FINAL':'EVALUACIÓN DEL MÓDULO'}</div>{done?<section className="question result"><Award size={35}/><h2>{score/questions.length>=.7?'Evaluación aprobada':'Evaluación no aprobada'}</h2><p>Nota: {Math.round(score/questions.length*100)}%. {score/questions.length>=.7?'Tu resultado ha sido guardado.':'Necesitas 70% para aprobar.'}</p><Link className="primary-btn" to={score/questions.length>=.7&&final?`/certificado/${p.id}`:`/curso/${p.id}`}>{score/questions.length>=.7&&final?'Ver certificado':'Volver al curso'}</Link></section>:<><h1>Comprueba lo que<br/>has <em>aprendido.</em></h1><div className="exam-progress"><span>Pregunta {step+1} de {questions.length}</span><Progress value={(step+1)/questions.length*100}/><span>{Math.round((step+1)/questions.length*100)}%</span></div><section className="question"><div className="question-number">{String(step+1).padStart(2,'0')}</div><h2>{q.question}</h2><p>Selecciona la respuesta más adecuada.</p>{q.options.map((x,i)=><button className={'option '+(answer===i?'chosen':'')} onClick={()=>setAnswer(i)} key={x}><i>{String.fromCharCode(65+i)}</i>{x}</button>)}<button className="primary-btn" disabled={answer===null} onClick={submit}>{step===questions.length-1?'Finalizar evaluación':'Siguiente pregunta'} <ArrowRight size={17}/></button></section></>}</main></>}
function CertificateV4(){const {id}=useParams();const user=currentUser();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const modules=savedModules().filter(m=>m.programId===p.id);if(!user)return <Navigate to="/ingresar" replace/>;const progress=readProgress(user,p.id);if(!progress.finalPassed||!modules.every(m=>progress.completed.includes(m.id)))return <Navigate to={`/curso/${p.id}`} replace/>;return <Certificate/>}
function AdminV5(){const nav=useNavigate();const [tab,setTab]=useState('Programas');const [ps,setPs]=useState(savedPrograms());const [us,setUs]=useState(savedUsers());const [ms,setMs]=useState(savedModules());const [title,setTitle]=useState('');const [text,setText]=useState('');const [programId,setProgramId]=useState(ps[0]?.id||'');const [moduleId,setModuleId]=useState('');const [options,setOptions]=useState('');const [correct,setCorrect]=useState(1);const [file,setFile]=useState('');const [message,setMessage]=useState('');if(currentUser()!=='admin')return <Navigate to="/ingresar" replace/>;const modules=ms.filter(m=>m.programId===programId);const saveP=(n:Program[])=>{setPs(n);savePrograms(n)};const reset=()=>{setTitle('');setText('');setOptions('');setFile('')};const onFile=(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>setFile(String(reader.result));reader.readAsDataURL(f)};const create=()=>{if(tab==='Programas'){if(!title)return;saveP([...ps,{id:title.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title,description:text||'Programa académico IESO.',duration:'10 semanas',modules:0,progress:0,color:'blue',icon:String(ps.length+1).padStart(2,'0')}]);setMessage('Programa publicado.')}if(tab==='Usuarios'){if(!title||!text)return;const n=[...us,{user:title,password:text,name:title}];setUs(n);saveUsers(n);setMessage('Cuenta de estudiante creada.')}if(tab==='Módulos'){if(!title||!programId)return;const n=[...ms,{id:crypto.randomUUID(),programId,title,content:text,material:file,video:'',quiz:''}];setMs(n);saveModules(n);saveP(ps.map(p=>p.id===programId?{...p,modules:n.filter(m=>m.programId===p.id).length}:p));setMessage('Módulo y material guardados.')}if(tab==='Evaluaciones'){const opt=options.split('\n').map(x=>x.trim()).filter(Boolean);if(!title||opt.length<2){setMessage('Incluye una pregunta y al menos dos opciones.');return}const all=savedQuizzes();if(!moduleId&&all.filter(q=>q.programId===programId&&!q.moduleId).length>=100){setMessage('La evaluación final admite máximo 100 preguntas.');return}saveQuizzes([...all,{id:crypto.randomUUID(),programId,moduleId:moduleId||undefined,question:title,options:opt,correct:Math.max(0,Math.min(opt.length-1,correct-1))}]);setMessage('Pregunta publicada en la evaluación.')}if(tab==='Anuncios'){if(!title||!text)return;saveAnnouncements([{id:crypto.randomUUID(),title,body:text,date:new Date().toLocaleDateString('es-CO')},...savedAnnouncements()]);setMessage('Anuncio publicado.')}reset()};const remove=(kind:string,id:string)=>{if(kind==='p')saveP(ps.filter(x=>x.id!==id));if(kind==='u'){const n=us.filter(x=>x.user!==id);setUs(n);saveUsers(n)}if(kind==='m'){const n=ms.filter(x=>x.id!==id);setMs(n);saveModules(n)}if(kind==='q')saveQuizzes(savedQuizzes().filter(x=>x.id!==id));setMessage('Elemento eliminado.')};const labels:any={Programas:['Crear programa','Nombre del programa','Descripción'],Usuarios:['Crear usuario','Usuario','Contraseña temporal'],Módulos:['Crear módulo','Título del módulo','Contenido de la lección'],Evaluaciones:['Añadir pregunta','Enunciado de la pregunta','Opciones: una por línea'],Anuncios:['Publicar anuncio','Título','Mensaje institucional']}[tab];return <div className="admin"><aside className="admin-nav"><Logo light/><div className="admin-label">ADMINISTRACIÓN</div>{[[BookOpen,'Programas'],[Users,'Usuarios'],[FileText,'Módulos'],[FileText,'Evaluaciones'],[Sparkles,'Anuncios'],[Award,'Certificados']].map(([I,x]:any)=><a className={tab===x?'active':''} onClick={()=>{setTab(x);reset();setMessage('')}} key={x}><I size={18}/>{x}</a>)}<div className="admin-bottom"><a onClick={()=>{localStorage.removeItem('ieso-session');nav('/')}}><Lock size={17}/>Cerrar sesión</a></div></aside><main className="admin-main"><div className="admin-top"><div><span>GESTIÓN IESO</span><h1>{tab}</h1></div></div>{tab==='Certificados'?<section className="admin-form"><h2>Certificados institucionales</h2><p>Solo se habilitan automáticamente tras todos los módulos aprobados y la evaluación final.</p><select value={programId} onChange={e=>setProgramId(e.target.value)}>{ps.map(p=><option value={p.id}>{p.title}</option>)}</select><Link className="add-btn" to={`/certificado/${programId}`}>Vista previa</Link></section>:<><section className="admin-form"><h2>{labels[0]}</h2>{['Módulos','Evaluaciones'].includes(tab)&&<select value={programId} onChange={e=>{setProgramId(e.target.value);setModuleId('')}}>{ps.map(p=><option value={p.id}>{p.title}</option>)}</select>}{tab==='Evaluaciones'&&<select value={moduleId} onChange={e=>setModuleId(e.target.value)}><option value="">Evaluación final del curso</option>{modules.map(m=><option value={m.id}>Final del módulo: {m.title}</option>)}</select>}<input value={title} onChange={e=>setTitle(e.target.value)} placeholder={labels[1]}/><textarea value={tab==='Evaluaciones'?options:text} onChange={e=>tab==='Evaluaciones'?setOptions(e.target.value):setText(e.target.value)} placeholder={labels[2]}/>{tab==='Evaluaciones'&&<><input value={String(correct)} onChange={e=>setCorrect(Number(e.target.value))} type="number" min="1" placeholder="Número de respuesta correcta"/><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Explicación o retroalimentación (opcional)"/></>}{tab==='Módulos'&&<label className="file-upload"><FileText size={16}/>{file?'Archivo adjunto':'Subir PDF, DOCX o material'}<input type="file" accept=".pdf,.doc,.docx" onChange={onFile}/></label>}<button className="add-btn" onClick={create}><Plus size={17}/>Guardar</button></section><section className="admin-table"><div className="table-head"><div><h2>{tab} publicados</h2></div></div>{tab==='Programas'&&ps.map(x=><div className="tr" key={x.id}><span><b>{x.title}</b></span><span>{x.modules} módulos</span><span><em>Activo</em></span><button className="plain-btn" onClick={()=>remove('p',x.id)}>Eliminar</button></div>)}{tab==='Usuarios'&&us.map(x=><div className="tr" key={x.user}><span><b>{x.user}</b></span><span>Estudiante</span><span><em>Autorizado</em></span><button className="plain-btn" onClick={()=>remove('u',x.user)}>Eliminar</button></div>)}{tab==='Módulos'&&ms.map(x=><div className="tr" key={x.id}><span><b>{x.title}</b></span><span>{ps.find(p=>p.id===x.programId)?.title}</span><span><em>{x.material?'Material adjunto':'Publicado'}</em></span><button className="plain-btn" onClick={()=>remove('m',x.id)}>Eliminar</button></div>)}{tab==='Evaluaciones'&&savedQuizzes().map(x=><div className="tr" key={x.id}><span><b>{x.question}</b></span><span>{x.moduleId?'Módulo':'Final'}</span><span><em>{x.options.length} opciones</em></span><button className="plain-btn" onClick={()=>remove('q',x.id)}>Eliminar</button></div>)}</section></>}{message&&<div className="admin-notice"><Check size={17}/>{message}</div>}</main></div>}
function CourseV6(){const {id}=useParams();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const user=currentUser();if(!user)return <Navigate to="/ingresar" replace/>;if(!hasProgramAccess(user,p.id))return <><NavV3/><main className="assessment"><section className="question"><Lock size={28}/><h2>Programa no autorizado</h2><p>Tu cuenta aún no tiene acceso a este programa. Solicita la autorización al administrador del IESO.</p><Link className="primary-btn" to="/programas">Ver programas</Link></section></main></>;return <CourseV4/>}
function AssessmentV6(){const {id}=useParams();const search=new URLSearchParams(location.search);const moduleId=search.get('module');const final=search.get('final')==='1';const user=currentUser();const p=savedPrograms().find(x=>x.id===id)||savedPrograms()[0];const modules=savedModules().filter(m=>m.programId===p.id);const progress=user?readProgress(user,p.id):{completed:[],finalPassed:false};const questions=savedQuizzes().filter(q=>q.programId===p.id&&((final&&!q.moduleId)||(!final&&q.moduleId===moduleId)));const [step,setStep]=useState(0);const [answer,setAnswer]=useState<number|null>(null);const [score,setScore]=useState(0);const [done,setDone]=useState(false);if(!user)return <Navigate to="/ingresar" replace/>;if(!hasProgramAccess(user,p.id))return <Navigate to={`/curso/${p.id}`} replace/>;if(final&&!modules.every(m=>progress.completed.includes(m.id)))return <Navigate to={`/curso/${p.id}`} replace/>;if(!questions.length)return <><NavV3/><main className="assessment"><section className="question"><h2>Evaluación pendiente de configurar</h2><p>El administrador debe publicar las preguntas antes de habilitarla.</p></section></main></>;const q=questions[step];const submit=()=>{if(answer===null)return;const next=score+(answer===q.correct?1:0);if(step<questions.length-1){setScore(next);setStep(step+1);setAnswer(null);return}const passed=next/questions.length>=.7;const grade:Grade={id:crypto.randomUUID(),user,programId:p.id,moduleId:final?undefined:moduleId||undefined,final,score:Math.round(next/questions.length*100),passed,date:new Date().toLocaleString('es-CO')};saveGrades([...savedGrades(),grade]);if(passed){saveProgress(user,p.id,final?{...progress,finalPassed:true}:{...progress,completed:[...new Set([...progress.completed,moduleId!])]})}setScore(next);setDone(true)};return <><NavV3/><main className="assessment"><div className="exam-label"><FileText/> {final?'EVALUACIÓN FINAL':'EVALUACIÓN MODULAR'}</div>{done?<section className="question result"><Award size={35}/><h2>{score/questions.length>=.7?'Evaluación aprobada':'Evaluación no aprobada'}</h2><p>Nota: {Math.round(score/questions.length*100)}%. {score/questions.length>=.7?'Tu avance fue guardado.':'Puedes estudiar el módulo e intentarlo nuevamente.'}</p><p className="feedback">{q.feedback||'El administrador no añadió retroalimentación para esta evaluación.'}</p><Link className="primary-btn" to={score/questions.length>=.7&&final?`/certificado/${p.id}`:`/curso/${p.id}`}>{score/questions.length>=.7&&final?'Ver certificado':'Volver al curso'}</Link></section>:<><h1>Comprueba lo que<br/>has <em>aprendido.</em></h1><div className="exam-progress"><span>Pregunta {step+1} de {questions.length}</span><Progress value={(step+1)/questions.length*100}/><span>{Math.round((step+1)/questions.length*100)}%</span></div><section className="question"><div className="question-number">{String(step+1).padStart(2,'0')}</div><h2>{q.question}</h2><p>Selecciona la respuesta más adecuada.</p>{q.options.map((x,i)=><button className={'option '+(answer===i?'chosen':'')} onClick={()=>setAnswer(i)} key={x}><i>{String.fromCharCode(65+i)}</i>{x}</button>)}<button className="primary-btn" disabled={answer===null} onClick={submit}>{step===questions.length-1?'Finalizar evaluación':'Siguiente pregunta'} <ArrowRight size={17}/></button></section></>}</main></>}
function AdminV6(){const nav=useNavigate();const [tab,setTab]=useState('Accesos');const [selected,setSelected]=useState(savedUsers()[0]?.user||'');const [enrollments,setEnrollments]=useState(savedEnrollments());const users=savedUsers();const programsNow=savedPrograms();const updateAccess=(programId:string)=>{const current=enrollments.find(x=>x.user===selected)?.programIds||[];const ids=current.includes(programId)?current.filter(x=>x!==programId):[...current,programId];const next=[...enrollments.filter(x=>x.user!==selected),{user:selected,programIds:ids}];setEnrollments(next);saveEnrollments(next)};const edit=(kind:string,id:string)=>{const value=window.prompt('Nuevo texto');if(value===null||!value.trim())return;if(kind==='program'){savePrograms(programsNow.map(x=>x.id===id?{...x,title:value}:x))}if(kind==='module'){saveModules(savedModules().map(x=>x.id===id?{...x,title:value}:x))}if(kind==='question'){saveQuizzes(savedQuizzes().map(x=>x.id===id?{...x,question:value}:x))}setTab(tab)};if(currentUser()!=='admin')return <Navigate to="/ingresar" replace/>;return <div className="admin"><aside className="admin-nav"><Logo light/><div className="admin-label">ADMINISTRACIÓN</div>{[[Users,'Accesos'],[FileText,'Notas'],[BookOpen,'Editar contenido'],[Plus,'Crear contenido']].map(([I,x]:any)=><a className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}><I size={18}/>{x}</a>)}<div className="admin-bottom"><a onClick={()=>{localStorage.removeItem('ieso-session');nav('/')}}><Lock size={17}/>Cerrar sesión</a></div></aside><main className="admin-main"><div className="admin-top"><div><span>GESTIÓN IESO</span><h1>{tab}</h1></div></div>{tab==='Accesos'&&<section className="admin-form"><h2>Autorización por programa</h2><p>Una cuenta solo podrá abrir los programas marcados aquí.</p><select value={selected} onChange={e=>setSelected(e.target.value)}>{users.map(u=><option value={u.user}>{u.user}</option>)}</select><div className="access-list">{programsNow.map(p=>{const checked=enrollments.find(x=>x.user===selected)?.programIds.includes(p.id)||false;return <label key={p.id}><input type="checkbox" checked={checked} onChange={()=>updateAccess(p.id)}/>{p.title}</label>})}</div></section>}{tab==='Notas'&&<section className="admin-table"><div className="table-head"><div><h2>Notas e intentos de estudiantes</h2><p>Registro de cada intento presentado.</p></div></div>{savedGrades().length?savedGrades().slice().reverse().map(g=><div className="tr" key={g.id}><span><b>{g.user}</b></span><span>{programsNow.find(p=>p.id===g.programId)?.title}</span><span>{g.final?'Final':'Módulo'} · {g.score}%</span><span><em>{g.passed?'Aprobado':'Reprobado'}</em></span></div>):<p className="empty">Aún no hay evaluaciones presentadas.</p>}</section>}{tab==='Editar contenido'&&<section className="admin-table"><div className="table-head"><div><h2>Editar contenido publicado</h2><p>Selecciona Editar para cambiar títulos rápidamente.</p></div></div>{programsNow.map(x=><div className="tr" key={x.id}><span><b>Programa · {x.title}</b></span><button className="plain-btn" onClick={()=>edit('program',x.id)}>Editar</button></div>)}{savedModules().map(x=><div className="tr" key={x.id}><span><b>Módulo · {x.title}</b></span><button className="plain-btn" onClick={()=>edit('module',x.id)}>Editar</button></div>)}{savedQuizzes().map(x=><div className="tr" key={x.id}><span><b>Pregunta · {x.question}</b></span><button className="plain-btn" onClick={()=>edit('question',x.id)}>Editar</button></div>)}</section>}{tab==='Crear contenido'&&<section className="admin-form"><h2>Crear y configurar contenido</h2><p>Usa el panel de creación para añadir programas, módulos, archivos PDF/DOCX, anuncios y preguntas de evaluaciones.</p><Link to="/gestion/contenido" className="add-btn">Abrir editor de contenido <ArrowRight size={16}/></Link></section>}</main></div>}
function App(){return <Routes><Route path="/" element={<HomeV4/>}/><Route path="/programas" element={<ProgramsV4/>}/><Route path="/anuncios" element={<Announcements/>}/><Route path="/curso/:id" element={<CourseV6/>}/><Route path="/evaluacion/:id" element={<AssessmentV6/>}/><Route path="/certificado/:id" element={<CertificateV4/>}/><Route path="/ingresar" element={<LoginV2/>}/><Route path="/gestion" element={<AdminV6/>}/><Route path="/gestion/contenido" element={<AdminV5/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes>}
createRoot(document.getElementById('root')!).render(<BrowserRouter><App/></BrowserRouter>)
